INSERT INTO question_bank
(category, level, tags, difficulty, question, reference_answer, source, status, created_at, updated_at)
VALUES
('销售认知与动机', '通用', '客户开拓,销售动机', 1, '为什么选择销售岗位？你认为销售最核心的特质是什么？', '可以从三点回答：第一，销售能直接接触客户和结果，成长反馈快；第二，自己具备目标感和抗压能力，愿意长期积累行业知识；第三，销售不是单纯能说会道，而是理解需求、整合资源并持续复盘。回答时要结合真实经历，不要只讲性格标签。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('销售认知与动机', '通用', '客户开拓,销售动机', 1, '你理解销售每天的日常工作是什么？', '销售的一天通常包括线索筛选、客户触达、拜访或线上沟通、方案准备、内部协同和 CRM 记录。不同阶段重点不同：早期重开拓，中期重需求确认和方案推进，后期重谈判和回款。优秀销售会把时间花在高质量商机上，而不是只追求拜访数量。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('销售认知与动机', '通用', '客户开拓,销售动机', 1, '做销售以来最有成就感的一件事是什么？', '用 STAR 讲一个具体案例：当时面对什么客户和任务，你做了哪些关键动作，最后拿到了什么结果。重点不是单子多大，而是你解决了什么难题、学到了什么。最好给出可量化结果，比如签约金额、回款周期或客户续约。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('销售认知与动机', '通用', '数据复盘,销售动机', 1, '连续几个月没有业绩，你会怎么调整？', '先稳住心态，不盲目加大无效拜访；然后复盘漏斗，看是线索量、转化率、客单价还是跟进节奏出了问题；再找主管或有经验的同事做陪访和案例复盘；最后调整动作，设定短期可验证的小目标，比如每周新增多少有效商机。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('销售认知与动机', '通用', '客户开拓,销售动机', 2, '新客户开拓和老客户维护，你更擅长哪一个？', '两者都重要，但我更擅长新客户开拓，因为喜欢从陌生到建立信任的过程，也积累了一套线索筛选和开场方法。老客户维护我也能做，会通过定期回访、增购和转介绍把客户价值做深。回答时最好各举一个例子。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('销售认知与动机', '通用', '需求挖掘,销售动机', 2, '如果这次面试没有通过，你觉得可能是什么原因？', '如果没通过，我首先会复盘三件事：是否没有把客户场景和结果讲清楚，是否对岗位所在行业理解不够，是否在压力问题下回答空泛。我也会向面试官请教具体反馈，把差距转成下一步学习计划，而不是简单归因于运气。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,线索开发', 1, '给你一个完全陌生的行业，你如何从零开发客户？', '先研究行业链条、典型客户和采购场景，列出目标客户画像；再通过工商信息、行业展会、协会、老客户转介绍等渠道找线索；然后设计有针对性的开场和价值假设，小批量触达并快速验证；最后把有效话术和无效话术记录下来，迭代客户名单。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,渠道', 1, '你常用哪些渠道找线索？如何判断渠道质量？', '常用渠道包括老客户转介绍、行业活动、内容获客、电话陌拜、合作伙伴和公开招投标信息。判断渠道质量不只看线索数量，要看有效联系人比例、需求匹配度、进入商机的比例和最终转化周期。定期按渠道复盘投入产出，砍掉低质量来源。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,线索判断', 2, '一条线索值不值得跟进，你会看哪些信号？', '我会看几个信号：客户是否有明确业务痛点，是否有预算和采购时间，联系人是否有决策影响力，是否愿意提供下一步信息。只有“有兴趣”但不愿约下一次沟通的线索，优先级会降低。线索判断不是凭感觉，要用可验证的问题去推进。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,资源不足', 2, '资源很少、起步很慢时，你如何破局？', '先把有限资源集中在最匹配的客户画像上，不广撒网；用老客户转介绍、行业社群和内容输出降低获客成本；同时把每次触达做成可复用素材，比如开场话术、案例和方案模板。短期接受慢，但要保证每个动作都能带来学习。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,陌拜', 2, '冷呼叫或陌拜时，你的开场白怎么设计？', '开场要短，先自报身份和来意，再用一个与客户行业相关的价值点引起注意，然后快速确认对方是否有时间。比如先问“你们现在在某某环节是否遇到某类问题”，而不是一上来介绍产品。被拒绝时礼貌结束并争取后续触达机会。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,转介绍', 2, '如何让老客户愿意给你转介绍？', '先把手头客户服务好，让客户愿意为结果背书；然后在交付节点或客户表达满意时，明确提出转介绍请求，说明希望认识哪类角色、为什么；最后降低对方成本，比如提供一段可直接转发的话术。转介绍不是随口要名片，而是基于信任的资源连接。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,活动获客', 3, '展会或线上活动拿到一批名单，你怎么跟进？', '活动结束后 24 小时内完成第一轮触达，按客户画像和互动记录分层；对高意向客户约深度沟通，对低意向客户用内容或案例培育；每次跟进都记录结果和下一步时间。名单不是越多越好，关键是把有限时间放在最可能有需求的客户上。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('客户开拓', '通用', '客户开拓,复盘', 3, '连续三个月没有新客户，你会怎么复盘？', '先复盘客户名单和触达过程，看是目标客户选错、开场没有价值、还是跟进节奏太慢；再请主管陪访，校正话术和判断；同时调整渠道结构，增加转介绍和行业活动；最后设定两周内可验证的改进指标，而不是只定一个遥远的签约目标。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,信任建立', 1, '第一次拜访客户，你如何开场并建立信任？', '先做功课，了解客户业务和可能的痛点；开场简明说明来意和对客户的理解，不急着讲产品；然后用一个开放问题请客户介绍现状和目标；最后确认本次沟通的议程和下一步。建立信任的关键是让客户感觉你懂他的业务，而不是来推销。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,痛点', 2, '客户只说要“基础方案”，你如何挖出真实需求？', '客户说“基础方案”往往不是没有需求，而是还没有把问题说透。我会先确认他当前的做法、成本和不满，再问如果不解决会有什么影响，最后用同类客户案例帮助他看到更高价值。不要直接否定客户，而是把需求从“功能”拉到“业务结果”。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,决策链', 2, '如何判断谁是关键决策人？', '通过组织架构、项目背景和多次沟通判断谁发起、谁使用、谁评估、谁拍板、谁付款。可以直接问客户“这类项目通常由哪些角色参与决策”，也可以在方案汇报时观察谁提问、谁做最终确认。不要只和维护人聊得热络就以为拿下了项目。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,干系人', 2, '多个部门诉求冲突时，你怎么办？', '先分别了解每个部门的诉求和顾虑，把冲突翻译成共同目标；再拉齐优先级和决策规则，必要时请客户高层或项目发起人定调；方案上可以做分阶段或模块化设计，先解决最核心的矛盾。销售的作用不是替客户做决定，而是帮客户把决策成本降下来。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,预算', 2, '预算、时间、决策权都不明确时，你先确认什么？', '先确认客户当前最想解决的问题和期望时间，再了解预算范围和审批流程，最后确认谁参与决策、谁有否决权。信息不明确时不要急着报价，可以通过“如果预算有限，您会优先解决哪一块”来试探优先级。越早确认这些，后面越少返工。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,变更管理', 3, '客户需求频繁变更，你如何管理？', '先判断变更是范围变化、理解偏差还是客户内部变化；然后书面确认变更内容、影响和成本，必要时调整方案或报价；同时和交付、售前对齐，避免销售单方面承诺。对频繁变更的客户，要建立固定的需求确认和复盘节奏。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,竞争切入', 3, '客户已有稳定供应商，你如何切入？', '不要一上来贬低竞品，而是找客户现有方案没有覆盖的场景或服务短板；可以从增量价值、响应速度、行业案例、总拥有成本等角度切入；先争取一个小范围试点或补充采购，用结果证明价值，再逐步扩大份额。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('需求挖掘与决策链', '通用', '需求挖掘,需求判断', 3, '如何区分“想要”和“必须买”的需求？', '我会问客户三个问题：这个问题现在造成了什么损失，是否已经影响业务指标；如果不解决，谁最着急；客户是否愿意为此投入预算和时间。愿意描述损失、有明确责任人和时间表的，通常是必须买；只是觉得“有了更好”的，先培育。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('方案呈现与价值', '通用', '方案呈现,价值表达', 1, '客户说功能很多但没价值，你怎么回应？', '先承认客户说得对，功能多不等于价值大；然后回到客户最关心的业务目标，挑出 1-2 个能直接解决问题的能力，用场景和结果讲清楚；最后确认这些价值是否值得客户投入。销售要敢做减法，而不是把产品手册念一遍。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('方案呈现与价值', '通用', '方案呈现,价值翻译', 2, '如何向非专业客户讲清产品价值？', '少讲术语，多讲客户熟悉的业务语言和结果，比如省了多少时间、减少多少损失、提升多少转化；用类比、流程图和案例帮助理解；每讲一个功能就对应一个客户场景。最后让客户用自己的话复述价值，确认他真的听懂了。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('方案呈现与价值', '通用', '方案呈现,ROI', 2, '你如何做一次 ROI 测算？', '先和客户确认投入项，包括采购成本、实施成本、培训和维护成本；再确认收益项，比如效率提升、人力节省、收入增长或风险损失降低；然后用客户认可的口径做保守测算，并标注假设。ROI 不是销售单方面算出来的漂亮数字，而是和客户一起验证的决策依据。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('方案呈现与价值', '通用', '方案呈现,竞品差异', 2, '竞品功能相似时，你如何讲差异化？', '先承认竞品在某些点上可能更强，避免陷入功能对比；然后回到客户的优先需求，讲我们在关键场景上的差异和证据，比如案例、服务响应、集成能力或总成本；最后用试点或分阶段方案降低客户决策风险。差异化要具体，不能只说“我们更好”。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('方案呈现与价值', '通用', '方案呈现,演示控场', 3, '演示被客户打断，说“我们用不上”，怎么办？', '先停下来确认客户的意思，是当前模块不相关，还是整体价值没讲清楚；如果是模块不匹配，就跳到客户关心的部分；如果是价值不认同，就回到需求和业务结果重新对齐。演示的目的不是讲完所有功能，而是让客户做出下一步决策。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('方案呈现与价值', '通用', '方案呈现,方案设计', 3, '定制化和标准化之间，你如何给客户建议？', '先判断客户需求是核心差异还是个性化偏好；如果是核心业务差异，可以评估定制成本和长期维护；如果只是使用习惯，优先用标准产品加配置解决。给客户建议时要讲清总成本、交付周期和升级风险，而不是为了签单盲目承诺。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,价格异议', 1, '客户说“太贵了”，你怎么处理？', '先确认客户是觉得绝对价格高，还是觉得价值不值；然后拆解价格构成和对应的服务范围，和客户一起算总拥有成本；再通过案例说明投入产出，必要时调整方案范围而不是直接降价。价格异议背后往往是价值没有讲透或预算不匹配。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,竞品异议', 1, '竞品比你们便宜 30%，你怎么回应？', '先了解竞品报价包含什么、是否有隐藏成本，避免只比表面价格；然后强调我们在关键场景、服务、稳定性和长期成本上的差异；如果客户确实价格敏感，可以提供分阶段方案或调整配置，但不轻易陷入无底线降价。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,拖延', 2, '客户说“我再考虑一下”，你怎么推进？', '先判断客户是礼貌拒绝还是确有顾虑；然后用开放问题确认他在考虑什么，是价格、风险、内部流程还是决策人意见；最后约定一个具体的下一步时间，比如下周几给反馈、需要提供什么材料。没有下一步的“再考虑”通常等于流失。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,需求异议', 2, '客户说“我们不需要”，你怎么判断真假？', '先区分是真不需要还是没意识到需求；通过行业趋势、同类客户案例和潜在损失帮助客户判断；如果客户确实没有需求，就礼貌结束并保持长期联系。销售不能把“不需要”硬拗成“需要”，但要把判断依据问清楚。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,预算异议', 2, '客户预算突然削减 20%，你如何调整方案？', '先确认削减的是总预算还是本项目预算，以及客户最不能放弃的目标；然后调整方案范围，优先保留核心价值，把非关键功能放到下一阶段；必要时调整付款节奏或交付周期。不要为了保住原报价而牺牲客户最在意的东西。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,情绪异议', 2, '客户态度很差并质疑产品，你怎么应对？', '先让客户把情绪和具体问题说完，不急着辩解；复述他的问题，确认你理解的是否准确；如果是产品问题，明确给出处理方案和时间；如果是误解，用事实和案例澄清。销售要能接住情绪，但也要守住专业边界。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,信任修复', 3, '客户觉得销售很烦，如何重新建立沟通？', '先减少无效打扰，尊重客户的沟通节奏；然后只在对客户有价值的时候出现，比如行业信息、案例或问题提醒；沟通时先问是否需要，再提供内容；用持续的专业输出重建信任。关系不是靠频繁刷存在感，而是靠每次出现都有价值。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('异议处理', '通用', '异议处理,流程推进', 3, '客户内部流程复杂、一直拖延，你怎么破局？', '先弄清楚卡在哪个环节、谁在推动、缺什么材料；然后主动提供模板、案例和内部汇报支持，帮助联系人降低推进成本；同时找到项目发起人或更高层确认优先级；最后设定阶段性节点，避免一直被动等待。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('谈判与成交', '通用', '谈判成交,价格谈判', 2, '签约前客户临时要求再降 20%，你怎么谈？', '先确认客户是预算真的不够，还是临门一脚试探；如果是预算问题，可以调整范围、付款方式或交付节奏，而不是直接降总价；如果是试探，要坚持价值并明确价格底线。任何让步都要换取对应承诺，比如签约时间、付款比例或案例授权。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('谈判与成交', '通用', '谈判成交,让步策略', 2, '你会用哪些条件换取价格让步？', '可以换取更长合同期、更高预付款比例、更多采购量、转介绍、案例授权、更快签约时间或更小的交付范围。让步前先确认对方最在意什么，让步后要落到书面。价格不是单独让的，每一次让步都要换回对等价值。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('谈判与成交', '通用', '谈判成交,成交信号', 2, '客户一直拖延不逼单，你如何确认成交信号？', '先判断客户是否已经具备决策条件，是流程慢、顾虑没解决还是优先级下降；然后确认成交信号，比如预算已批、方案已认可、时间表明确；最后用具体节点推进，比如确认合同版本、付款安排或启动时间。逼单不是催，而是帮客户完成决策。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('谈判与成交', '通用', '谈判成交,关系风险', 3, '关键联系人突然离职，合同怎么推进？', '先确认项目是否仍然立项、新的决策人是谁；然后尽快通过原联系人、项目发起人或高层重新建立联系；把前期共识、方案和价值材料整理成可交接的文件；同时评估项目延期风险，调整销售预测。不要把项目绑在一个人身上。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('谈判与成交', '通用', '谈判成交,合同谈判', 3, '合同条款或回款方式有分歧，你怎么处理？', '先区分是商务条款、法务风险还是现金流问题；然后在公司底线内设计替代方案，比如分期付款、里程碑付款、履约保证或调整交付范围；需要时拉上法务和财务一起和客户沟通。销售不能为了签单承诺公司无法履约的条件。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('谈判与成交', '通用', '谈判成交,大客户推进', 3, '长周期项目如何分阶段推进和成交？', '把项目拆成需求确认、方案验证、试点、商务谈判和全面推广几个阶段，每个阶段设定明确的交付物和决策节点；同时管理客户内部流程和预算周期；用阶段性成果降低客户风险，也让自己有可预测的销售节奏。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('过程管理与数据复盘', '通用', '数据复盘,目标拆解', 2, '月度目标你会怎么拆解到每周每天？', '先按历史转化率和客单价倒推需要多少商机、多少有效拜访和多少线索；再拆到每周和每天，并留出缓冲；然后每周复盘实际进度和漏斗变化，及时调整渠道和跟进优先级。目标拆解不是简单除以天数，而是从结果倒推动作。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('过程管理与数据复盘', '通用', '数据复盘,漏斗管理', 2, '你如何用漏斗和 CRM 管理商机？', '把客户按阶段管理，比如线索、初步接触、需求确认、方案、谈判、成交；每个阶段设定进入和退出标准，记录下一步动作和时间；每周看各阶段转化率和停留时间，找出卡点。CRM 不是填表任务，而是帮助自己判断哪里需要投入。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('过程管理与数据复盘', '通用', '数据复盘,丢单复盘', 3, '丢单后你会复盘哪些内容？', '先确认丢单原因，是价格、方案、关系、时机还是客户预算取消；然后回看关键节点，哪些信息没确认、哪些承诺没兑现、哪个决策人没覆盖；最后形成改进行动，比如调整客户画像、优化话术或加强售前协同。复盘要落到下一次可执行的动作。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('过程管理与数据复盘', '通用', '数据复盘,动作评估', 3, '你如何用数据判断某个销售动作是否有效？', '先定义动作对应的指标，比如陌拜看有效联系率和约访率，方案看推进率和反馈周期，活动看名单转化率；然后对比不同时间段、渠道和客户群的表现；最后保留有效动作，淘汰低效动作。数据要能指导下一步，而不是只做汇报。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('行为与抗压', '通用', '谈判成交,行为案例', 1, '讲一个你最有成就感的销售案例（STAR）。', '按情境、任务、行动、结果讲：客户当时面临什么问题，你负责什么目标，你做了哪些关键动作，最后结果如何。重点讲你个人的判断和动作，不要把所有成绩归因于团队或运气。结果最好量化，并补充你从中学到了什么。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('行为与抗压', '通用', '异议处理,抗压', 1, '讲一次被客户拒绝的经历，你当时怎么做的？', '讲一个具体被拒绝的场景，说明客户拒绝的真实原因，你当时如何调整心态、如何复盘、后续是否还有跟进；最后说明这次经历让你改进了什么。不要只说“我不怕拒绝”，要证明你能从拒绝里提取信息。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('行为与抗压', '通用', '需求挖掘,团队协作', 2, '你和售前、交付或团队发生冲突时怎么处理？', '先讲清楚冲突背景和各方目标，说明你如何分别沟通、找到共同目标、推动解决方案；如果自己有责任，要明确承认；最后说明结果和关系是否修复。销售需要整合售前、交付和财务资源，冲突处理能力很重要。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3)),
('行为与抗压', '通用', '客户开拓,抗压', 2, '目标很难完成时，你第一步会做什么？', '先把大目标拆成可验证的小目标和关键动作，确认最优先的客户和商机；然后盘点资源，找出缺口，向主管争取支持；同时设定每周检查点，根据数据调整策略。面对难目标，先行动和验证，而不是被目标大小吓住。', '公开面经整理（改写）', 'ACTIVE', CURRENT_TIMESTAMP(3), CURRENT_TIMESTAMP(3));
INSERT INTO track_question (track_id, question_id, sort_order, weight, enabled, created_at, updated_at)
